import logging
from subprocess import Popen, PIPE
from ipaddress import IPv6Address, ip_address
from six import u


def is_ip_v6(ip):
    try:
        ip = ip.decode('utf-8', 'ignore')
    except AttributeError:
        pass
    try:
        ip = u(ip)
    except TypeError:
        pass
    return isinstance(ip_address(ip), IPv6Address)


def nmap_check(ip, port):
    logging.info("Checking open ports...")
    cmd = _build_nmap_cmd(ip, port)
    stdout, ret_code = _call_cmd(cmd)
    if 'open'.encode("utf8") not in stdout or ret_code is None:
        raise Exception("OAM node port is closed")
    return True


def _build_nmap_cmd(ip, port):
    """ Builds nmap command (discovers IPv6
    and adds `-6` flag to indicate IPv6) """
    if is_ip_v6(ip):
        nmap = 'nmap -p {port} -oG - -6 {ip} | grep {port}/open'
    else:
        nmap = 'nmap -p {port} -oG - {ip} | grep {port}/open'
    cmd = nmap.format(ip=ip, port=port)
    return cmd


def _call_cmd(cmd):
    proc = Popen(cmd, stdout=PIPE, stderr=PIPE, shell=True)
    stdout, stderr = proc.communicate()
    ret_code = proc.poll()
    logging.debug("{} stdout: {}".format(cmd, stdout))
    logging.debug("{} stderr: {}".format(cmd, stderr))
    return stdout, ret_code
